draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // face
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();

  // eyes
  ctx.fillStyle = '#000000';
  ctx.beginPath();
  ctx.arc(W/2 - 20, H/2 - 20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 20, H/2 - 20, 10, 0, 2 * Math.PI);
  ctx.fill();

  // mouth
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 20, 20, 0, Math.PI);
  ctx.stroke();

  // sour face reaction
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 + 40);
  ctx.lineTo(W/2 - 10, H/2 + 60 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2 + 40);
  ctx.lineTo(W/2 + 10, H/2 + 60 + 20 * Math.sin(t));
  ctx.stroke();

  // lemon
  ctx.fillStyle = '#ffff00';
  ctx.beginPath();
  ctx.arc(W/2 + 80, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.fill();

  // knife
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2 - 30);
  ctx.lineTo(W/2 + 90, H/2 - 30);
  ctx.stroke();

  // slicing motion
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2 + 80, H/2 - 50);
  ctx.lineTo(W/2 + 80, H/2 - 50 + 20 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
